-- PLANETBINTANG VendorDomain platform modules migration
-- PostgreSQL 15+. Apply only after reviewed backup and approved migration window.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS auth_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_factors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, factor_type text NOT NULL, secret_ref text NOT NULL, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS role_permissions (role text NOT NULL, permission text NOT NULL, resource_scope text NOT NULL DEFAULT 'tenant', PRIMARY KEY(role,permission,resource_scope));
CREATE TABLE IF NOT EXISTS service_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, service_key text NOT NULL, audience text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,service_key,audience));
CREATE TABLE IF NOT EXISTS gateway_routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_key text NOT NULL UNIQUE, method text NOT NULL, path_pattern text NOT NULL, upstream_ref text NOT NULL, version text NOT NULL, enabled boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id) ON DELETE SET NULL, event_type text NOT NULL, schema_version text NOT NULL, payload jsonb NOT NULL, idempotency_key text NOT NULL UNIQUE, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, source_key text NOT NULL, cursor_value text, conflict_policy text NOT NULL DEFAULT 'manual', status text NOT NULL DEFAULT 'queued', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS provider_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_key text NOT NULL, environment text NOT NULL CHECK(environment IN ('sandbox','production')), secret_ref text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_key,environment));
CREATE TABLE IF NOT EXISTS storage_buckets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, provider_key text NOT NULL, bucket_name text NOT NULL, region text NOT NULL, encryption_required boolean NOT NULL DEFAULT true, UNIQUE(tenant_id,provider_key,bucket_name));
CREATE TABLE IF NOT EXISTS backup_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id) ON DELETE CASCADE, resource_ref text NOT NULL, status text NOT NULL DEFAULT 'planned', checksum text, encrypted boolean NOT NULL DEFAULT true, started_at timestamptz, completed_at timestamptz);
CREATE TABLE IF NOT EXISTS security_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id) ON DELETE CASCADE, severity text NOT NULL CHECK(severity IN ('info','low','medium','high','critical')), finding_key text NOT NULL, status text NOT NULL DEFAULT 'open', details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS service_catalog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_key text NOT NULL UNIQUE, version text NOT NULL, capabilities jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS marketplace_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_ref text NOT NULL, service_key text NOT NULL REFERENCES service_catalog(service_key), status text NOT NULL DEFAULT 'pending', approval_ref text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, meter_key text NOT NULL, quantity numeric(24,8) NOT NULL CHECK(quantity>=0), source_ref text NOT NULL, idempotency_key text NOT NULL UNIQUE, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS billing_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, entry_type text NOT NULL CHECK(entry_type IN ('debit','credit')), amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency char(3) NOT NULL, reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_intents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, provider_key text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0), currency char(3) NOT NULL, status text NOT NULL DEFAULT 'created', idempotency_key text NOT NULL UNIQUE, provider_ref text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enterprise_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, sla_tier text NOT NULL, quota jsonb NOT NULL DEFAULT '{}'::jsonb, approval_ref text NOT NULL, valid_until timestamptz);
CREATE INDEX IF NOT EXISTS idx_sessions_user_expiry ON auth_sessions(user_id,expires_at);
CREATE INDEX IF NOT EXISTS idx_outbox_pending ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_usage_tenant_time ON usage_records(tenant_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_backup_tenant_status ON backup_jobs(tenant_id,status);
CREATE INDEX IF NOT EXISTS idx_security_open ON security_findings(tenant_id,severity) WHERE status='open';
